const input = $input.first().json;
const body = input.body ?? input;
const changes = body.changes || [];
let diffText = '';
for (const c of changes) {
  diffText += `
### ${c.new_path || c.old_path}
`;
  diffText += (c.diff || '').slice(0, 12000);
}
if (!diffText.trim()) diffText = '(無 diff 內容)';
const prompt = `你是資深 Code Reviewer。請審核以下 GitLab Merge Request 變更。

專案: ${body.projectName}
MR: !${body.mrIid} - ${body.title}
作者: ${body.authorName || 'unknown'}

請用繁體中文回覆，並嚴格輸出 JSON（不要 markdown code fence）：
{
  "summary": "一句話摘要",
  "suggestions": "Markdown 條列建議",
  "fullReview": "完整審核說明",
  "severity": 1-5 整數
}

--- DIFF ---
${diffText}`;
return [{ json: { reviewId: body.reviewId, callbackUrl: body.callbackUrl, projectName: body.projectName, mrIid: body.mrIid, prompt } }];

const prev = $('Code_組裝Prompt').first().json;
const ai = $input.first().json;
function extractAiText(payload) {
  if (!payload) return '';
  if (typeof payload === 'string') return payload;
  if (payload.choices?.[0]?.message?.content) return payload.choices[0].message.content;
  if (Array.isArray(payload)) return extractAiText(payload[0]);
  if (payload.content?.parts?.[0]?.text) return payload.content.parts[0].text;
  if (payload.candidates?.[0]?.content?.parts?.[0]?.text) return payload.candidates[0].content.parts[0].text;
  return '';
}
let content = extractAiText(ai) || JSON.stringify(ai);
content = content.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '');
let parsed;
try { parsed = JSON.parse(content); } catch (e) { parsed = { summary: 'AI 回覆解析失敗', suggestions: content, fullReview: content, severity: 3 }; }
function suggestionsToText(suggestions) {
  if (!suggestions) return '';
  if (typeof suggestions === 'string') return suggestions;
  if (Array.isArray(suggestions)) return suggestions.filter(Boolean).map((s) => (String(s).trim().startsWith('- ') ? String(s).trim() : `- ${String(s).trim()}`)).join('\n\n');
  return String(suggestions);
}
const suggestionsText = suggestionsToText(parsed.suggestions);
return [{ json: { reviewId: prev.reviewId, callbackUrl: prev.callbackUrl, status: 'COMPLETED', summary: parsed.summary || '', suggestions: suggestionsText, fullReview: parsed.fullReview || suggestionsText || content, severity: Number(parsed.severity) || 3 } }];
